            flex-direction: column;
            align-items: center;
            padding: 0 10px;
            transition: transform 0.3s ease;
        }
        .data-block:hover {
            transform: scale(1.02);
        }
        .block-title {
            background-color: var(--seal-bg-color);
            color: var(--seal-text-color);
            padding: 12px 6px;
            border-radius: 5px;
            font-size: 1.3rem;
            text-align: center;
            writing-mode: horizontal-tb;
            margin-bottom: 15px;
            box-shadow: 2px 2px 3px rgba(0,0,0,0.2);
            font-family: 'SimSun', 'STSong', serif;
            animation: sealStamp 0.5s ease-out forwards;
            animation-delay: 0.2s;
            opacity: 0;
        }
        .data-item {
            font-size: 1.1rem;
            letter-spacing: 0.15em;
            line-height: 1.7;
            margin-bottom: 5px;
            white-space: nowrap;
        }
        .data-key { color: #5c4e3e; font-weight: bold; }
        .divider {
            width: 2px;
            background-image: var(--divider-texture);
            background-repeat: repeat-y;
            background-size: contain;
            opacity: 0.7;
            margin: 0 8px;
        }
        .page-2-content {
            animation: inkFadeIn 0.8s ease-out forwards;
        }
        .page-2-content .data-item {
            margin-bottom: 12px;
            font-size: 1.05rem;
            line-height: 1.8;
            letter-spacing: 1px;
        }
        .page-2-content .data-key {
            font-weight: bold;
            font-size: 1.15rem;
            color: var(--seal-bg-color);
        }
        .page-2-content .data-value {
            display: block;
            margin-top: 3px;
            padding-left: 1em;
            text-align: justify;
            white-space: pre-wrap;
        }
        .flip-instruction {
            position: absolute;
            bottom: 10px;
            left: 50%;
            transform: translateX(-50%);
            font-family: var(--font-family);
            color: #777;
            cursor: pointer;
            z-index: 3;
            background: rgba(255,255,255,0.5);
            padding: 3px 8px;
            border-radius: 5px;
            font-size: 0.8rem;
        }
    </style>
</head>
<body>
    <div class="ledger-data-container">$1</div>
    <div class="ledger-container" id="ledgerContainer">
        <div class="ledger-book" id="ledgerBook">
            <div class="page" id="page-1">
                <div class="page-header"><span>萬象津</span><span class="dot">·</span><span>風聞錄</span></div>
                <div class="scrollable-content-wrapper">
                    <div class="scrollable-content">
                        <div class="content-wrapper" id="page1Content"></div>
                    </div>
                </div>
            </div>
            <div class="page" id="page-2">
                 <div class="page-header"><span>紅顏</span><span class="dot">·</span><span>私密</span></div>
                 <div class="scrollable-content-wrapper">
                     <div class="scrollable-content">
                        <div class="page-2-content" id="page2Content"></div>
                     </div>
                 </div>
            </div>
        </div>
        <div class="flip-instruction" id="flipButton">【 轻触翻页 】</div>
    </div>
    <script>
    document.addEventListener('DOMContentLoaded', () => {
        const dataContainer = document.querySelector('.ledger-data-container');
        const ledgerContainer = document.getElementById('ledgerContainer');
        const flipButton = document.getElementById('flipButton');
        const page1Content = document.getElementById('page1Content');
        const page2Content = document.getElementById('page2Content');

        if (!dataContainer || !ledgerContainer) return;

        function parseData(text) {
            const data = {};
            const blockRegex = /\[(\S+?)\]([\s\S]*?)\[\/\1\]/g;
            let match;
            while ((match = blockRegex.exec(text)) !== null) {
                const blockName = match[1];
                const blockContent = match[2].trim();
                const items = {};
                const lines = blockContent.split('\n');
                let currentKey = null;
                let currentValue = '';
                lines.forEach(line => {
                    const parts = line.match(/^([^:]+):\s*([\s\S]*)/);
                    if (parts) {
                        if (currentKey) items[currentKey] = currentValue.trim();
                        currentKey = parts[1].trim();
                        currentValue = parts[2].trim();
                    } else if (currentKey) {
                        currentValue += '\n' + line.trim();
                    }
                });
                if (currentKey) items[currentKey] = currentValue.trim();
                data[blockName] = items;
            }
            return data;
        }

        function renderPage1(data) {
            if (!data) return;
            const overview = data['江湖总览'];
            if (!overview) return;

            page1Content.innerHTML = `
                <div class="data-block">
                    <div class="block-title">立足<br>之地</div>
                    <div class="data-item"><span class="data-value">${overview['时辰'] || '未知'}</span></div>
                    <div class="data-item"><span class="data-value">${overview['区域'] || '未知'}</span></div>
                </div>
                <div class="divider"></div>
                <div class="data-block">
                    <div class="block-title">江湖<br>風評</div>
                    <div class="data-item"><span class="data-key">金玉坊：</span><span class="data-value">${overview['金玉坊'] || '无'}</span></div>
                    <div class="data-item"><span class="data-key">鱼龙里：</span><span class="data-value">${overview['鱼龙里'] || '无'}</span></div>
                    <div class="data-item"><span class="data-key">烟柳巷：</span><span class="data-value">${overview['烟柳巷'] || '无'}</span></div>
                    <div class="data-item"><span class="data-key">百工坊：</span><span class="data-value">${overview['百工坊'] || '无'}</span></div>
                    <div class="data-item"><span class="data-key">衙门渡：</span><span class="data-value">${overview['衙门渡'] || '无'}</span></div>
                </div>
                <div class="divider"></div>
                <div class="data-block">
                    <div class="block-title">腰間<br>之物</div>
                    <div class="data-item"><span class="data-key">盘缠：</span><span class="data-value">${overview['盘缠'] || '无'}</span></div>
                    <div class="data-item"><span class="data-key">信物：</span><span class="data-value">${overview['信物'] || '无'}</span></div>
                </div>
                <div class="divider"></div>
                <div class="data-block">
                    <div class="block-title">悬赏<br>榜文</div>
                    <div class="data-item"><span class="data-key">任务：</span><span class="data-value">${overview['任务'] || '暂无'}</span></div>
                    <div class="data-item"><span class="data-key">报酬：</span><span class="data-value">${overview['报酬'] || '无'}</span></div>
                </div>
            `;
        }

        function renderPage2(data) {
            if (!data) return;
            const confidante = data['红颜一瞥'];
            if (!confidante || !confidante['姓名']) {
                page2Content.innerHTML = '<div class="data-item">此刻无人，唯有风月。</div>';
                return;
            }

            let html = `<div class="data-item"><span class="data-key">【芳名】</span><span class="data-value">${confidante['姓名']}</span></div>`;
            const fields = ['姿势', '服饰', '身体反应', '心理想法', '对你的看法', '玉峰', '幽谷', '谷道'];
            const fieldTitles = ['身姿', '衣着', '反应', '心绪', '评语', '玉峰', '幽谷', '谷道'];

            fields.forEach((field, index) => {
                if(confidante[field]){
                    html += `<div class="data-item"><span class="data-key">【${fieldTitles[index]}】</span><span class="data-value">${confidante[field]}</span></div>`;
                }
            });
            page2Content.innerHTML = html;
        }

        flipButton.addEventListener('click', () => {
            ledgerContainer.classList.toggle('flipped');
        });

        const rawData = dataContainer.textContent.trim();
        if (rawData) {
            const parsedData = parseData(rawData);
            renderPage1(parsedData);
            renderPage2(parsedData);
        } else {
            page1Content.innerHTML = '风闻录暂无内容。';
            page2Content.innerHTML = '风闻录暂无内容。';
        }
    });
    </script>
</body>
</html>
